//! Test vectors, generated by a script kept outside the repository from the
//! files below; do not edit by hand.
//!
//! [`CFRG`] is every vector of RFC 9180's test-vector file
//! (<https://github.com/cfrg/draft-irtf-cfrg-hpke>, `test-vectors.json`) in
//! this crate's scope: DHKEM(P-256), DHKEM(P-521) and DHKEM(X25519) (the file
//! has none for P-384), each with HKDF-SHA256 or HKDF-SHA512 (none with
//! HKDF-SHA384) and AES-128-GCM, AES-256-GCM or export-only, in each of the
//! four modes. The suites that RFC 9180 prints in Appendix A (A.1, A.3, A.4,
//! A.6 and A.7) keep the six encryptions it prints (sequence numbers 0, 1, 2,
//! 4, 255 and 256), checked against the RFC's text with every other value
//! of theirs; the others keep two of their 257 (0 and 256). Every encryption
//! in the file seals the same plaintext with the associated data
//! `Count-<sequence number>`, which lets the tests rebuild the ones in
//! between.
//!
//! [`GO_ACCUMULATED`] is every vector of Go's crypto/hpke tests
//! (`src/crypto/hpke/testdata/rfc9180.json`, Go 1.27.1) in the same scope:
//! Base mode only, each with a SHAKE128 hash of 1000 encryptions and one of
//! 1000 exports, made from inputs drawn from a SHAKE128 stream.

/// One vector of RFC 9180's file, in hex. Fields of a mode that does not
/// use them (the sender's keys outside the authenticated modes, the PSK
/// outside the PSK modes) are empty, as are the key and base nonce of the
/// export-only AEAD. `appendix` is the section of RFC 9180 that prints the
/// suite, or empty.
pub(super) struct Vector {
    pub(super) appendix: &'static str,
    pub(super) mode: u8,
    pub(super) kem_id: u16,
    pub(super) kdf_id: u16,
    pub(super) aead_id: u16,
    pub(super) info: &'static str,
    pub(super) ikm_r: &'static str,
    pub(super) sk_rm: &'static str,
    pub(super) pk_rm: &'static str,
    pub(super) ikm_e: &'static str,
    pub(super) ikm_s: &'static str,
    pub(super) sk_sm: &'static str,
    pub(super) pk_sm: &'static str,
    pub(super) psk: &'static str,
    pub(super) psk_id: &'static str,
    pub(super) enc: &'static str,
    pub(super) shared_secret: &'static str,
    pub(super) key: &'static str,
    pub(super) base_nonce: &'static str,
    pub(super) exporter_secret: &'static str,
    pub(super) encryptions: &'static [Encryption],
    pub(super) exports: &'static [Export],
}

/// One encryption of a vector: the ciphertext of `pt` under `aad` at
/// sequence number `seq`.
pub(super) struct Encryption {
    pub(super) seq: u32,
    pub(super) aad: &'static str,
    pub(super) pt: &'static str,
    pub(super) ct: &'static str,
}

/// One export of a vector: `len` bytes for `context`.
pub(super) struct Export {
    pub(super) context: &'static str,
    pub(super) len: usize,
    pub(super) value: &'static str,
}

